function examCdTimestamp(date) {
    if(typeof date !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(date)) return NaN;
    const parts = date.split('-').map(Number), value = Date.UTC(parts[0], parts[1] - 1, parts[2]), day = new Date(value);
    return day.getUTCFullYear() === parts[0] && day.getUTCMonth() === parts[1] - 1 && day.getUTCDate() === parts[2] ? value : NaN;
}
function examCdList() {
    const raw = jparse(ukey('examCountdown'), []), list = Array.isArray(raw) ? raw : [];
    return list.filter(x => x && typeof x.name === 'string' && Number.isFinite(examCdTimestamp(x.date))).slice(0, 10);
}
function examCdDays(date) {
    const target = examCdTimestamp(date); if(!Number.isFinite(target)) return NaN;
    const today = calToday().split('-').map(Number);
    return Math.round((target - Date.UTC(today[0], today[1] - 1, today[2])) / 86400000);
}
